export function gitBranchName(ref: string): string {
  invariant(
    ref.startsWith("refs/heads/") && ref.length > 11,
    "Expected a full Git branch ref.",
  );
  return `git-${hash(ref).slice(0, 40)}`;
}

export function lexicalQuery(
  query: string,
  filters: { path?: string; language?: string } = {},
): Record<string, unknown> {
  invariant(
    query.trim().length > 0 && query.length <= 4096,
    "Query must contain 1–4096 characters.",
  );
  const literal = (field: string, value: string) => ({
    queryString: { query: value, defaultField: field, skipSyntax: true },
    occur: "filter",
  });
  return {
    bool: [
      literal("kind", "chunk"),
      {
        queryString: { query, defaultField: "searchText", skipSyntax: true },
        occur: "must",
      },
      ...(filters.path ? [literal("path", filters.path)] : []),
      ...(filters.language ? [literal("language", filters.language)] : []),
    ],
  };
}

export function developmentVersion(version, count) {
  const match = devPattern.exec(version);
  if (!match || !/^[1-9]\d*$/.test(String(count)))
    throw new Error(
      "Develop requires X.Y.Z-dev.N and a positive first-parent commit count.",
    );
  return `${match[1]}.${match[2]}.${match[3]}-dev.${count}`;
}

const u = new URL(s.endpoint);
const local = ["localhost", "127.0.0.1", "[::1]"].includes(u.hostname);
invariant(
  (u.protocol === "https:" || (local && u.protocol === "http:")) &&
    !u.username &&
    !u.password &&
    !u.search &&
    !u.hash &&
    u.pathname === "/",
  "Endpoint must be an HTTPS origin (HTTP loopback is allowed).",
);

const file = await one(store, tag(v.tagName), h.fileId);
invariant(
  file?.kind === "file" &&
    file.configHash === h.repository.configHash &&
    file.path === h.path &&
    typeof file.sourceText === "string" &&
    file.contentHash === h.contentHash &&
    hash(Buffer.from(file.sourceText)) === h.contentHash,
  "Original source is missing or its hash does not match.",
);

if (j) {
  invariant(
    j.buildId === b.buildId &&
      j.recordsHash === b.recordsHash &&
      j.inventoryHash === b.inventoryHash &&
      (j.gitRef === b.branchRef ||
        (j.reuseWriter === undefined && j.writer.startsWith("work-"))),
    "Another build is pending. Resume the artifact recorded in pending.json before importing a new commit.",
  );
  invariant(
    args.resume,
    "Pending import found; use --resume with the same artifact.",
  );
}

const current = (await store.tags()).find((t) => t.name === v.tagName);
invariant(
  current?.snapshotId === v.snapshotId,
  "Pinned Tag was deleted or recreated.",
);

const attemptId = randomUUID();
j = {
  buildId: b.buildId,
  recordsHash: b.recordsHash,
  inventoryHash: b.inventoryHash,
  artifact: b.directory,
  attemptId,
  writer: `work-${attemptId}`,
  source,
  baseline,
  phase: "branch",
  batches: [],
};
